/*
 * Stack values for the PostScript mini-interpreter...
 */

typedef enum
{
  CUPS_PS_NAME,
  CUPS_PS_NUMBER,
  CUPS_PS_STRING,
  CUPS_PS_BOOLEAN,
  CUPS_PS_NULL,
  CUPS_PS_START_ARRAY,
  CUPS_PS_END_ARRAY,
  CUPS_PS_START_DICT,
  CUPS_PS_END_DICT,
  CUPS_PS_START_PROC,
  CUPS_PS_END_PROC,
  CUPS_PS_CLEARTOMARK,
  CUPS_PS_COPY,
  CUPS_PS_DUP,
  CUPS_PS_INDEX,
  CUPS_PS_POP,
  CUPS_PS_ROLL,
  CUPS_PS_SETPAGEDEVICE,
  CUPS_PS_STOPPED,
  CUPS_PS_OTHER
} _cups_ps_type_t;

typedef struct
{
  _cups_ps_type_t       type;           /* Object type */
  union
  {
    int         boolean;                /* Boolean value */
    char        name[64];               /* Name value */
    double      number;                 /* Number value */
    char        other[64];              /* Other operator */
    char        string[64];             /* String value */
  }                     value;          /* Value */
} _cups_ps_obj_t;

typedef struct
{
  int                   num_objs,       /* Number of objects on stack */
                        alloc_objs;     /* Number of allocated objects */
  _cups_ps_obj_t        *objs;          /* Objects in stack */
} _cups_ps_stack_t;


/*
